  'prompts.info':
    '每个部件按顺序取第一个有改动的来源：此 Bot 的改动、Bot 选的预设、全局预设，最后是内置文字。预设只保存它改过的部件，没改过的部件会跟随内置文字的更新。\n\n正在运行的会话会继续使用它开始时的文字，这样提示词缓存不会失效，同一会话里的行为也前后一致。改动会在 Bot 的下一个会话或下一次上下文压缩时写入，在那之前显示“待生效”。\n\n如果你改过的部件对应的内置文字后来更新了，会显示“默认已更新”，可以查看新的默认文字后决定是否保留自己的版本。',
