  'intro.title': 'Welcome to Tobs',
  'intro.progress': 'Step {current} of {total}',
  'intro.step.welcome': 'Meet Tob',
  'intro.step.theme': 'Look',
  'intro.step.model': 'Model',
  'intro.step.community': 'Community',
  'intro.step.start': 'Start',
  'intro.welcome.greeting': 'Hi, I’m Tob',
  'intro.welcome.body':
    'My name is Bot spelled backwards: Tob. I’m your local steward. Ask me to create Bots, start groups and plan tasks, or ask what each Bot has been up to. Every Bot here has its own personality and memory, and remembers what you talked about.',
  'intro.welcome.next': 'Take a minute to make this place yours, then let’s get started.',
  'intro.founder.title': 'From the founder',
  'intro.founder.body':
    'When I started building Tobs, I was a student in human-computer interaction (HCI). Along the way I published a paper at HAI, and the agents I manage now double every three months.\nI believe that one day IM apps will hold more bots than humans. Tobs has been shaped with that future in mind, around two ideas:\n1. Build the IM app for the next era of agents.\n2. Carry on the openness of DeepSeek Harness, where everything is a plugin.\nIt is shaped not only by me, but by this open-source community: every person and every bot.',
  'intro.founder.signature': '— DoodleBear',
  'intro.reviews.title': 'What people say',
  'intro.reviews.clean': '“Clean and uncluttered. Lots of features, yet I find things fast.”',
  'intro.reviews.era': '“This is going to define an era!”',
  'intro.reviews.details': '“So many small clever touches and polished details.”',
  'intro.theme.title': 'Pick a look you like',
  'intro.theme.scheme': 'Color mode',
  'intro.theme.color': 'Theme color',
  'intro.theme.wallpaper': 'Wallpaper',
  'intro.theme.panels': 'Panels',
  'intro.theme.panelsHint': 'With a wallpaper, adjust panel opacity and blur.',
  'intro.model.title': 'Choose a default model',
  'intro.model.hint': 'Tob and new Bots use it. You can change it in Settings later.',
  'intro.model.saved': 'Saved',
  'intro.model.advanced': 'Advanced',
  'intro.model.advancedSame': 'Main and task models are the same',
  'intro.model.advancedSplit': 'Tob uses a separate task model',
  'intro.model.assignmentHint':
    'Tob runs delegated tasks on this model. When it differs from the main model, Tob stops following the default model.',
