  'intro.persona.tasksTitle': 'Starter tasks for you',
  'intro.persona.change': 'Pick another',
  'intro.persona.promptsTitle': 'Starter tasks for {persona}',
  'intro.persona.promptsHint':
    'Each task uses one thing Tob can do. Send one to Tob and it walks you through it.',
  'intro.persona.timeZone':
    ' My time zone is {timeZone}. Confirm the saved time, the next run and where it will be delivered.',
  'intro.persona.timeZoneUnknown':
    ' My browser could not detect my time zone, so ask me which one I use before creating the real schedule.',
  'intro.persona.engineer.name': 'Engineers',
  'intro.persona.engineer.hint': 'Code, review PRs, run services',
  'intro.persona.engineer.reviewer.title': 'Create a code review Bot',
  'intro.persona.engineer.reviewer.body':
    'Create a Bot called “Code Reviewer” that knows my stack, reviews my code, points out risks and missing tests, and keeps our team’s coding conventions in its memory. Ask me which languages and frameworks I use first.',
  'intro.persona.engineer.squad.title': 'Set up a tech squad group chat',
  'intro.persona.engineer.squad.body':
    'Create a group chat called “Tech Squad” with an “Architect” Bot and a “Test Engineer” Bot. When I post a requirement there, they split the work: one discusses the design, the other adds test cases.',
  'intro.persona.engineer.releases.title': 'Open-source digest every weekday morning',
  'intro.persona.engineer.releases.body':
    'Create a schedule for 9:00 every weekday that summarizes, in this DM, yesterday’s new releases and notable issues from the open-source projects I follow, with links. Ask me which projects to follow first.',
  'intro.persona.creator.name': 'Creators',
  'intro.persona.creator.hint': 'Find topics, write, publish',
  'intro.persona.creator.trends.title': 'Search this week’s hot topics',
  'intro.persona.creator.trends.body':
    'Search the web for the 5 most-discussed AI topics this week. For each, give a one-line summary and an angle for a short video or post, with the source links you actually found. If the search fails, say so instead of making up sources.',
  'intro.persona.creator.editor.title': 'Create a topic editor Bot',
  'intro.persona.creator.editor.body':
    'Create a Bot called “Topic Editor” that remembers my channel’s positioning, audience and writing style, and later helps me edit drafts, write titles and brainstorm topics. Ask me a few questions about my channel first.',
  'intro.persona.creator.brief.title': 'Morning trend brief every day',
  'intro.persona.creator.brief.body':
    'Create a schedule for 8:00 every day that sends me a trend brief in this DM: 3–5 items, each with a source link and an angle I could take.',
  'intro.persona.operator.name': 'Product / Ops',
  'intro.persona.operator.hint': 'Specs, teamwork, weekly reports',
  'intro.persona.operator.team.title': 'Set up a product team group chat',
  'intro.persona.operator.team.body':
    'Create a group chat called “Product Team” with a “User Research” Bot and a “Competitor Analysis” Bot. I’ll describe a new feature there and they’ll advise from the user and competitor angles.',
  'intro.persona.operator.im.title': 'Connect a Bot to Lark or Discord',
  'intro.persona.operator.im.body':
    'I want my colleagues to reach a Bot directly in Lark or Discord. Tell me how to connect a Bot to these apps in Tobs: what I need to prepare, who can talk to it, and which permissions to watch.',
  'intro.persona.operator.weekly.title': 'Weekly report reminder on Fridays',
  'intro.persona.operator.weekly.body':
    'Create a schedule for 17:00 every Friday that reminds me in this DM to write my weekly report, with a first draft based on what we talked about this week.',
  'intro.persona.learner.name': 'Students / Researchers',
  'intro.persona.learner.hint': 'Learn, read papers, research',
  'intro.persona.learner.tutor.title': 'Create a study buddy Bot',
  'intro.persona.learner.tutor.body':
    'Create a Bot called “Study Buddy” that helps me make a study plan. Ask me what I want to learn, my current level and how much time I have each week first.',
  'intro.persona.learner.papers.title': 'Find a few things worth reading',
  'intro.persona.learner.papers.body':
    'Search the web for 3 recent high-quality papers or long reads on AI agents, summarize each in three sentences, and include the links you actually found. If the search fails, say so instead of making up sources.',
  'intro.persona.learner.goals.title': 'Remember my long-term goal',
  'intro.persona.learner.goals.body':
    'Ask me a few questions about the exam or research topic I’m working toward, my goal and deadline, then save them to your memory and plan my progress around them every time we talk.',
  'intro.feature.bot': 'Create a Bot',
  'intro.feature.group': 'Group chat',
  'intro.feature.schedule': 'Schedule',
  'intro.feature.browser': 'Web search',
  'intro.feature.memory': 'Memory',
