  'intro.interview.timeZone': ' My time zone is {timeZone}.',
  'intro.interview.title': 'Interview me and set things up',
  'intro.interview.hint':
    'Not sure yet? Tob asks one question at a time, then suggests the Bots, group chats and schedules to set up. Nothing is created until you confirm.',
  'intro.interview.body':
    'Interview me to set up my starting environment in Tobs. Ask one question at a time, at most 6, about my job, daily work, the tools I use and what I most want to hand to Bots. Then propose a plan: which Bots to create (name and role), whether to set up group chats, and what to turn into schedules. Wait for my confirmation before creating anything, and save the key facts about me to your memory.',
