  'prompts.showDefault': 'Show the new default',
  'prompts.pendingHint':
    "Changes take effect at the Bot's next Session or its next context compaction.",
  'prompts.info':
    "Each part takes its text from the first layer that changes it: this Bot's edits, the Bot's chosen preset, the global preset, then the built-in text. A preset stores only the parts it changes; untouched parts follow updates to the built-in text.\n\nA running Session keeps the text it started with, so the prompt cache stays valid and the Bot behaves consistently within a Session. A change is written at the Bot's next Session or next context compaction and shows as Pending until then.\n\nIf the built-in text of a part you edited is later updated, the part shows Default updated so you can read the new default and decide whether to keep your version.",
